from functools import lru_cache

from app.db.chroma import text_collection
from app.services.retrieval_service import Retriever


@lru_cache(maxsize=1)
def get_retriever() -> Retriever:
    """One retriever for the app; upload/delete routes call .invalidate() on it."""
    return Retriever(text_collection())


def validate_session_id(value: str) -> str:
    """Sessions are random UUID v4 strings generated by the browser. This is a lightweight
    isolation mechanism, NOT authentication: anyone who obtains the UUID can use the session
    (see docs/security.md)."""
    import uuid

    from app.errors import AppError

    try:
        parsed = uuid.UUID(str(value))
    except ValueError:
        raise AppError(400, "session_id must be a valid UUID v4.") from None
    if parsed.version != 4:
        raise AppError(400, "session_id must be a valid UUID v4.")
    return str(parsed)


def resolve_session_id(session_id: str | None, header_session_id: str | None) -> str:
    """Resolve the header first while retaining the query parameter for compatibility."""
    return validate_session_id(header_session_id or session_id or "")
